import{_ as a,r as o,o as l,c as s,e as n,a as e,s as i,d as t}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"Планирование задач - October CMS - 1.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Введение","slug":"введение","link":"#введение","children":[]},{"level":2,"title":"Создание","slug":"создание","link":"#создание","children":[{"level":3,"title":"Параметры частоты выполнения","slug":"параметры-частоты-выполнения","link":"#параметры-частоты-выполнения","children":[{"level":4,"title":"Произвольное условие","slug":"произвольное-условие","link":"#произвольное-условие","children":[]}]},{"level":3,"title":"Предотвращение перекрытия задач","slug":"предотвращение-перекрытия-задач","link":"#предотвращение-перекрытия-задач","children":[]}]},{"level":2,"title":"Вывод","slug":"вывод","link":"#вывод","children":[]},{"level":2,"title":"Хуки","slug":"хуки","link":"#хуки","children":[{"level":4,"title":"Pinging URLs","slug":"pinging-urls","link":"#pinging-urls","children":[]}]}],"relativePath":"1.x/ru/plugin/scheduling.md","filePath":"1.x/ru/plugin/scheduling.md"}'),p={name:"1.x/ru/plugin/scheduling.md"};function h(u,d,g,m,f,y){const c=o("pre-heading"),r=o("post-heading");return l(),s("div",null,[n(c),d[0]||(d[0]=e("h1",null,"Планирование задач",-1)),n(r),d[1]||(d[1]=i(`<p><a name="introduction" class="anchor"></a></p><h2 id="введение"><a href="#введение" class="header-anchor">#</a> Введение</h2><p>Раньше разработчики настраивали через SSH крон на сервере для каждой новой задачи. Теперь Вы можете использовать плагины! Нужно указать лишь одну запись в кроне!</p><blockquote><p><strong>Примечание</strong>: См. [руководство по установке](../setup/installation#crontab-setup для настройки крона.</p></blockquote><p><a name="defining-schedules" class="anchor"></a></p><h2 id="создание"><a href="#создание" class="header-anchor">#</a> Создание</h2><p>Вы можете определить все запланированные задачи в методе <code>registerSchedule</code> в <a href="./registration.html#registration-file">классе регистрации плагина</a>. Метод принимает один аргумент <code>$schedule</code>.</p><p>Пример:</p><pre><code>class Plugin extends PluginBase
{
    [...]

    public function registerSchedule($schedule)
    {
        $schedule-&gt;call(function () {
            \\Db::table(&#39;recent_users&#39;)-&gt;delete();
        })-&gt;daily();
    }
}
</code></pre><p>Вы также можете вызывать <a href="./../console/commands.html">консольные команды</a> по расписанию. Пример:</p><pre><code>$schedule-&gt;command(&#39;cache:clear&#39;)-&gt;daily();
</code></pre><p>Используйте <code>exec</code> для создания команд операционной системе:</p><pre><code>$schedule-&gt;exec(&#39;node /home/acme/script.js&#39;)-&gt;daily();
</code></pre><p><a name="schedule-frequency-options" class="anchor"></a></p><h3 id="параметры-частоты-выполнения"><a href="#параметры-частоты-выполнения" class="header-anchor">#</a> Параметры частоты выполнения</h3><div class="table"><table tabindex="0"><thead><tr><th>Метод</th><th>Описание</th></tr></thead><tbody><tr><td><code>-&gt;cron(&#39;* * * * *&#39;);</code></td><td>Выполнить задачу в произвольный момент времени</td></tr><tr><td><code>-&gt;everyMinute();</code></td><td>Выполнять задачу каждую минуту</td></tr><tr><td><code>-&gt;everyFiveMinutes();</code></td><td>Выполнять задачу каждые 5 минут</td></tr><tr><td><code>-&gt;everyTenMinutes();</code></td><td>Выполнять задачу каждые 10 минут</td></tr><tr><td><code>-&gt;everyThirtyMinutes();</code></td><td>Выполнять задачу каждые пол часа</td></tr><tr><td><code>-&gt;hourly();</code></td><td>Выполнять задачу каждый час</td></tr><tr><td><code>-&gt;daily();</code></td><td>Выполнять задачу каждый день в полночь</td></tr><tr><td><code>-&gt;dailyAt(&#39;13:00&#39;);</code></td><td>Выполнять задачу каждый день в 13:00</td></tr><tr><td><code>-&gt;twiceDaily(1, 13);</code></td><td>Выполнять задачу каждый день в 01:00 и 13:00</td></tr><tr><td><code>-&gt;weekly();</code></td><td>Выполнять задачу каждую неделю</td></tr><tr><td><code>-&gt;monthly();</code></td><td>Выполнять задачу каждый месяц</td></tr></tbody></table></div><p>Эти методы могут сочетаться с дополнительными условиями для создания более тонкой настройки. Пример задачи, которая выполняется еженедельно в понедельник в 13:00:</p><pre><code>$schedule-&gt;call(function () {
    // Runs once a week on Monday at 13:00...
})-&gt;weekly()-&gt;mondays()-&gt;at(&#39;13:00&#39;);
</code></pre><p>Дополнительные условия:</p><div class="table"><table tabindex="0"><thead><tr><th>Метод</th><th>Описание</th></tr></thead><tbody><tr><td><code>-&gt;weekdays();</code></td><td>в будние дни</td></tr><tr><td><code>-&gt;sundays();</code></td><td>по воскресеньям</td></tr><tr><td><code>-&gt;mondays();</code></td><td>по понедельникам</td></tr><tr><td><code>-&gt;tuesdays();</code></td><td>по вторникам</td></tr><tr><td><code>-&gt;wednesdays();</code></td><td>по средам</td></tr><tr><td><code>-&gt;thursdays();</code></td><td>по четвергам</td></tr><tr><td><code>-&gt;fridays();</code></td><td>по пятницам</td></tr><tr><td><code>-&gt;saturdays();</code></td><td>по субботам</td></tr><tr><td><code>-&gt;when(Closure);</code></td><td>произвольное условие</td></tr></tbody></table></div><h4 id="произвольное-условие"><a href="#произвольное-условие" class="header-anchor">#</a> Произвольное условие</h4><p>Метод <code>when</code> используется для ограничения выполнения задачи. Другими словами, если заданное <code>Closure</code> возвращает<code> true</code>, задача будет выполняться до тех пор, пока не наступит другое условие:</p><pre><code>$schedule-&gt;command(&#39;emails:send&#39;)-&gt;daily()-&gt;when(function () {
    return true;
});
</code></pre><p><a name="preventing-task-overlaps" class="anchor"></a></p><h3 id="предотвращение-перекрытия-задач"><a href="#предотвращение-перекрытия-задач" class="header-anchor">#</a> Предотвращение перекрытия задач</h3><p>По умолчанию запланированные задачи будут выполняться, даже если предыдущий экземпляр все еще запущен. Чтобы предотвратить это, Вы можете использовать метод <code>withoutOverlapping</code>:</p><pre><code>$schedule-&gt;command(&#39;emails:send&#39;)-&gt;withoutOverlapping();
</code></pre><p><a name="task-output" class="anchor"></a></p><h2 id="вывод"><a href="#вывод" class="header-anchor">#</a> Вывод</h2><p>Планировщик предоставляет несколько удобных методов для работы с результатами, которые генерируют задачами. Во-первых, используя метод <code>sendOutputTo</code>, Вы можете отправить результат в файл для последующей проверки:</p><pre><code>$schedule-&gt;command(&#39;emails:send&#39;)
         -&gt;daily()
         -&gt;sendOutputTo($filePath);
</code></pre><p>Вы также можете отправить результаты задачи на почту при помощи метода <code>emailOutputTo</code>, но после того как запишите их в файл. Не забудьте настроить <a href="./../services/mail.html">почтовый сервис</a>:</p><pre><code>$schedule-&gt;command(&#39;foo&#39;)
         -&gt;daily()
         -&gt;sendOutputTo($filePath)
         -&gt;emailOutputTo(&#39;foo@example.com&#39;);
</code></pre><blockquote><p><strong>Примечание:</strong> Вы можете использовать методы <code>emailOutputTo</code> и <code>sendOutputTo</code> только с методом <code>command</code>!.</p></blockquote><p><a name="task-hooks" class="anchor"></a></p><h2 id="хуки"><a href="#хуки" class="header-anchor">#</a> Хуки</h2><p>Используйте методы <code>before</code> и<code> after</code>, чтобы указать код, который должен быть выполнен до или после завершения запланированной задачи:</p><pre><code>$schedule-&gt;command(&#39;emails:send&#39;)
         -&gt;daily()
         -&gt;before(function () {
             // Task is about to start...
         })
         -&gt;after(function () {
             // Task is complete...
         });
</code></pre><h4 id="pinging-urls"><a href="#pinging-urls" class="header-anchor">#</a> Pinging URLs</h4><p>Используйте методы <code>pingBefore</code> и<code> thenPing</code>, чтобы автоматически пинговать заданный URL до или после завершения задачи. Этот метод полезен для уведомления внешней службы о том, что запланированное задание начинается или завершается:</p><pre><code>$schedule-&gt;command(&#39;emails:send&#39;)
         -&gt;daily()
         -&gt;pingBefore($url)
         -&gt;thenPing($url);
</code></pre>`,41)),d[2]||(d[2]=e("blockquote",null,[e("p",null,[t("Вы должны установить "),e("a",{href:"http://octobercms.com/plugin/october-drivers",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[t("Drivers plugin"),e("span",null,[e("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[e("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),t(),e("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),t(),e("span",{class:"sr-only"},"(opens new window)")])]),t(" перед тем как использовать "),e("code",null,"pingBefore($url)"),t(" или "),e("code",null,"thenPing($url)"),t(".")])],-1))])}const k=a(p,[["render",h]]);export{b as __pageData,k as default};
